const labels=Object.assign({},...Object.values(permissionGroups));
const legacyPermissionMap={'clients.read':['clients.view'],'clients.write':['clients.create','clients.edit','clients.delete','clients.references'],'assets.write':['clients.references'],'users.manage':['users.view','users.create','users.edit','users.delete'],'roles.manage':['roles.view','roles.create','roles.edit','roles.delete'],'flows.read':['flows.view'],'flows.write':['flows.create','flows.edit','flows.configure','flows.run','flows.approve','flows.reject'],'boards.read':['boards.view'],'boards.write':['boards.create','boards.edit','boards.delete','boards.cards.create','boards.cards.edit','boards.cards.archive','boards.columns.manage','boards.members.manage','boards.labels.manage','boards.comments.create']};
function normalizeRolePermissions(role){if(!role)return role;const raw=role.permissions||[];const granular=raw.filter(permission=>labels[permission]);const migrated=granular.length?granular:raw.flatMap(permission=>legacyPermissionMap[permission]||[permission]).filter(permission=>labels[permission]);const system=role.id==='role-admin'||role.system;const all=system?Object.keys(labels):migrated;const legacy=system?Object.keys(legacyPermissionMap):raw.filter(permission=>Object.hasOwn(legacyPermissionMap,permission));role.permissions=[...new Set([...all,...legacy])];return role;}
